from pathlib import Path
from html.parser import HTMLParser
root=Path('/app/output')
class P(HTMLParser):
    def __init__(self): super().__init__(); self.hrefs=[]; self.scripts=[]; self.links=[]; self.controls=[]; self.ids=set()
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if 'id' in d: self.ids.add(d['id'])
        if tag=='a' and 'href' in d: self.hrefs.append(d['href'])
        if tag=='script' and 'src' in d: self.scripts.append(d['src'])
        if tag=='link' and 'href' in d: self.links.append(d['href'])
        if 'aria-controls' in d: self.controls.append(d['aria-controls'])
for path in root.glob('*.html'):
    parser=P(); parser.feed(path.read_text())
    missing=[]
    for ref in parser.scripts+parser.links:
        if not (root/ref).exists(): missing.append(ref)
    for href in parser.hrefs:
        if href and not href.startswith(('#','http','mailto:')) and not (root/href.split('#')[0]).exists(): missing.append(href)
    missing_controls=[c for c in parser.controls if c not in parser.ids]
    print(path.name, 'missing refs', missing, 'missing aria-controls', missing_controls[:5], 'ids', len(parser.ids))
